          def: 'Levitt（1960）提出：企業以「自己生產什麼產品」而非「顧客要滿足什麼需要」來定義事業範圍，導致看不見真正的競爭者與市場變化。',
          tip: '講「鐵路業不是敗給別條鐵路，是敗給公路和飛機，因為他們以為自己在做鐵路而不是做運輸」，最快讓教授知道你懂。'
