      title: 'STP 的整體邏輯與市場區隔的理由',
      tags: ['必考', '核心'],
      source: 'Smith（市場區隔, 1956）；Kotler & Keller',
      brief: `**STP 是現代行銷策略的骨幹**：Segmentation（區隔）→ Targeting（選目標）→ Positioning（定位）。它回答三個問題：市場上有哪些不同的人？我要服務誰？我要在他們心中站什麼位置？

**為什麼要區隔？** 因為顧客異質。大眾行銷（mass marketing）假設所有人需求相同，用同一套 4P 打全部人。這在供不應求的年代可行，但一旦競爭者出現，他只要專攻其中一群人、把產品做得更貼合，就能把那群人整批拿走。

所以區隔的本質是：**用資源集中換取貼合度**。放棄一部分市場，換取在目標市場上的相對優勢。

STP 一定在 4P 之前——**先決定為誰而戰，才決定怎麼打**。`,
      advanced: `**大眾行銷並非全然錯誤**，它在特定條件下仍然有效：產品高度標準化（食鹽、汽油）、規模經濟極強、或品牌本身就是訴求最大公約數的日用品。所以正確的說法是「大眾行銷的**適用範圍縮小**」，而非被淘汰。

**區隔的三個層次**（由粗到細）：
1. **區隔行銷**：把市場切成幾群，選一到多群服務
2. **利基行銷**：切得更細，服務被大廠忽略的小群體。利基的特徵是規模小但需求明確、顧客願意付溢價、大廠進入不划算
3. **個體行銷／客製化**：極端情形下區隔到「一人一個市場」。數位技術（推薦演算法、動態定價、程式化廣告）讓這件事的成本大幅下降

**過度區隔的風險**是申論的加分點：切得太細會導致規模不經濟、產品線複雜度失控、品牌訊息分散。實務上要在「貼合度」與「規模效率」之間取捨，這也是為什麼許多品牌會用「主副品牌」而非無限延伸產品線。

**STP 與其他架構的關係**：STP 之前通常先做環境分析（PEST、五力、SWOT），之後才進 4P。完整的策略行銷流程是：**環境分析 → STP → 4P → 執行與控制**。面試被問「你會怎麼幫某品牌做行銷規劃」時，照這條路講就不會亂。`,
      example: `**手搖飲市場**是台灣最好的區隔教材。同樣是茶飲，可以按「價格帶」（50 嵐 vs 春水堂）、按「使用場合」（上班提神 vs 下午茶社交）、按「健康意識」（無糖純茶 vs 加料珍奶）、按「生活型態」（外送族 vs 排隊打卡族）切出完全不同的市場。同一杯飲料，選擇不同的區隔基礎，會得到完全不同的競爭者名單——這正是區隔會影響策略的原因。`,
