      title: '購買決策過程五階段',
      tags: ['必考', '核心'],
      source: 'Engel-Kollat-Blackwell（EKB 模型）；Kotler & Keller',
      brief: `**購買決策五階段**（EKB 模型）：

1. **需要察覺**：內在刺激（餓）或外在刺激（廣告）觸發
2. **資訊搜尋**：內部搜尋（記憶）＋ 外部搜尋（親友、廣告、網路、經驗）
3. **方案評估**：用一組屬性權重評估備選品牌，形成偏好
4. **購買決策**：他人態度與意外情境仍可能改變決定
5. **購後行為**：滿意（回購、口碑）／不滿意（抱怨、退貨、負面口碑）

**兩個關鍵洞見**：

- **購買決策不等於購買行為**。第 3 階段結束時已經「決定要買什麼」，但第 4 階段還會被親友一句話或門市缺貨改變。「已決定但沒買」是行銷失守的常見位置。
- **購後行為屬於下一次購買的第 2 階段**（記憶）。所以顧客的每一次滿意都是下次獲客的成本節省——這是關係行銷把資源從獲客轉向留存的心理基礎。`,
      advanced: `**五階段不是每次購買都會完整走過**。它是一個描述**高涉入複雜購買**的完整流程；日常低涉入購買（買口香糖）可能只有「察覺→買」兩階段，中間全部跳過。因此考題常搭配「涉入度」一起考。

**資訊搜尋的兩個關鍵集合**：
- **知覺集合（awareness set）**：顧客知道的所有品牌
- **考慮集合（consideration set）**：顧客真的納入評估的品牌，通常 3–5 個

行銷的一大目標就是**擠進考慮集合**——沒進去，後面所有品質、價格、通路都沒機會發揮。這正是品牌知名度的策略價值：知名度低不僅少一個曝光，是連被評估的資格都沒有。

**方案評估的兩種模型**（考題會出）：
- **補償性模型**：屬性可以互補，A 屬性差可以用 B 屬性強來彌補（加權加總）
- **非補償性模型**：任一屬性未達門檻就直接淘汰，不管其他屬性多強
  - 連接式（conjunctive）：所有屬性都要過門檻
  - 分離式（disjunctive）：只要有一個關鍵屬性極突出就選
  - 詞典式（lexicographic）：先比最重要屬性，同分再比第二重要

**購後行為受期望失驗理論驅動**（見 [[mkt-01-04]]）。此外還有兩個進階概念：

- **認知失調（cognitive dissonance）**：高單價、不易退換的購買後，顧客會懷疑「我是不是買錯了」。企業可透過**購後溝通**（感謝信、使用教學、開箱手冊）主動降低失調，這是很多汽車與精品品牌花大錢做「已購顧客關懷」的原因。
- **顧客旅程（customer journey）**：Kotler 行銷 4.0 提出的 5A（Aware、Appeal、Ask、Act、Advocate）是 EKB 五階段的數位化版本，多了最後的 **Advocate（推薦）**——現代顧客不只購後回購，還會主動推薦或抱怨，成為下一輪的資訊源。`,
      example: `**買一台筆電**會完整走完五階段：舊機變慢或看到廣告觸發需要（察覺）；上網爬文、看評測、問朋友、去實體店摸機（搜尋）；把 CPU、螢幕、重量、價格、品牌信任度做權重比較（評估）；到現場發現想買的型號缺貨、店員推另一款、或朋友一句「那牌服務很爛」都可能改變決定（購買）；買完後如果散熱不佳，會後悔、抱怨、影響下次購買（購後）。

反過來，**買一杯手搖飲**幾乎沒有搜尋與評估——路過看到→買，這正是低涉入。這也解釋了為什麼手搖飲的通路密度（Place）遠比廣告（Promotion）重要。`,
