          sample: `消費者購買決策依 EKB 模型分為五個階段。**需要察覺**由內在或外在刺激觸發顧客意識到現況與理想狀態的落差。**資訊搜尋**包含記憶中的內部搜尋與親友、廣告、網路、實體體驗等外部搜尋。**方案評估**時顧客依一組屬性權重比較備選品牌，形成偏好排序，並形成僅 3–5 個品牌的**考慮集合**。**購買決策**即依偏好做出選擇，但**此階段完成的是「決定要買什麼」而非「已經買了」**——親友的一句話、門市缺貨、突發財務狀況都可能改變實際購買。**購後行為**則決定顧客的滿意程度，並成為下一次購買的內部資訊源。

值得強調的是，這**五階段是描述高涉入複雜購買的完整流程**，並非所有購買都會完整經歷。**涉入度**指顧客對該次購買結果的重要性判斷與投入程度，受產品價格、風險、與自我形象相關性、資訊複雜度等因素影響。

以**筆記型電腦**為高涉入例。價格昂貴、使用週期長、且與工作生產力密切相關，顧客會完整走過五階段：舊機變慢或看到廣告觸發需要；上網爬文、看評測、詢問朋友、實體店試機構成密集的資訊搜尋；將 CPU、螢幕、重量、續航、售後服務、品牌信任度賦予權重比較；到店可能因缺貨、店員推薦或朋友的負評改變決定；購後若散熱不佳將出現明顯的**認知失調**，需要企業以感謝信、使用教學等購後溝通主動降低。此類產品的行銷組合重心在於**塑造知覺品質、進入考慮集合、經營試用體驗與購後關懷**，廣告投資應與內容行銷、口碑經營併行。

以**手搖飲**為低涉入例。價格低、風險低、無需長期承諾，顧客的實際流程往往是「路過看到→買」，中間的搜尋與評估幾乎跳過。此類產品的行銷組合重心因而轉向**通路密度**（走到哪都看得到）、**陳列與招牌辨識度**（一眼認出）、以及**新品輪替**（維持察覺階段的觸發）。廣告的邊際效益遠低於再開一家店，這正是手搖飲品牌極少投入電視廣告卻拚命展店的原因。

綜合而言，涉入度不同不僅是消費者投入程度的差別，更決定了企業行銷資源的正確配置方向。忽略此一差異而套用同一套 4P 模板，是行銷計畫最常見的浪費來源。`
