            '對 IMC 實務的意涵二：SEO、評論管理、NPS 成為新的必要投資',
            '對 IMC 實務的意涵三：BAR 成為比 PAR 更根本的指標',
            '結論：模型的演進反映的是消費者行為的結構性變化，而非行銷理論的自我更新'
