      brief: `Kotler 用五個版本描述行銷典範的演進：

| 版本 | 導向 | 核心問題 |
|---|---|---|
| **1.0** | 產品導向 | 怎麼把東西做出來、賣出去 |
| **2.0** | 消費者導向 | 顧客是誰、要什麼（STP 誕生） |
| **3.0** | 價值觀導向 | 我們為什麼存在（品牌使命） |
| **4.0** | 數位轉型 | 線上線下如何整合（顧客旅程） |
| **5.0** | 科技為人 | 科技如何服務人性 |

**三個關鍵轉折**：

- **1.0 → 2.0**：從「生產什麼賣什麼」轉為「顧客要什麼做什麼」，這是行銷觀念的誕生（見 [[mkt-01-02]]）。
- **2.0 → 3.0**：顧客不只是有需求的消費者，而是**有價值觀的完整的人**。品牌必須回答「你為什麼存在」，不能只回答「你賣什麼」。
- **4.0 → 5.0**：4.0 處理的是「怎麼數位化」，5.0 處理的是「**數位化之後，人的位置在哪**」。核心命題是 **Technology for Humanity**——科技是手段，提升人的體驗才是目的。

**注意「演進」不等於「取代」**，跟五種行銷觀念一樣：5.0 時代的企業仍然需要把產品做好（1.0）、仍然需要做 STP（2.0）。`,
      advanced: `**行銷 5.0 的五大要素**（Kotler, 2021，考題會出）：

1. **資料驅動行銷（Data-Driven）**：建立顧客資料生態系，讓決策有依據
2. **預測式行銷（Predictive）**：用模型預測顧客行為與行銷成效
3. **情境行銷（Contextual）**：依顧客當下的實體情境提供個人化互動（地點、時間、狀態）
4. **擴增行銷（Augmented）**：用科技**增強**而非取代第一線人員（客服有 AI 輔助，但難題仍由人處理）
5. **敏捷行銷（Agile）**：小規模快速實驗、快速迭代，取代大型年度計畫

**「擴增」這個詞選得很精準**：Kotler 明確反對用科技全面取代人員。理由是——高情感涉入、複雜、有爭議的互動，顧客仍需要人；科技應該處理重複性事務，把人力釋放到真正需要判斷力的地方。這是回答「AI 會不會取代行銷人員」時最好的架構。

**數位轉型最常見的誤解**：把「東西搬上網」當成數位轉型。開一個官網、做一個 App、開粉專，這些只是**通路數位化**。真正的數位轉型是**重新設計顧客旅程**——資料在各接觸點之間流動、線上線下的體驗互相銜接、決策由資料驅動。

**判斷是不是真的數位轉型的三個問句**：
1. 顧客在線上的行為，線下的店員看得到嗎？
2. 各部門看到的是同一份顧客資料嗎？
3. 決策是靠資料還是靠會議上聲音最大的人？

**世代差異是 5.0 的重要前提**。Kotler 特別指出 Y 世代（千禧）、Z 世代與 Alpha 世代的差異：Z 世代是**數位原生**，對品牌真誠度極度敏感、拒絕說教式廣告、重視即時與個人化；Alpha 世代則是**完全在螢幕中長大**的第一代。同時也存在**數位落差**——高齡與偏鄉族群可能被排除在數位服務之外，這既是社會議題也是市場機會。`,
      example: `**台灣超商的咖啡寄杯**是很好的數位轉型例子，因為它不是「把東西搬上網」，而是**數位化才可能存在的商業模式**。

過去買咖啡是一手交錢一手交貨。寄杯把它拆成兩件事：**現在付錢、未來任意門市任意時間取貨**。這需要會員系統、跨店庫存、電子憑證才做得到——是先有數位基礎建設，才有這個商業模式。

它同時創造三個價值：對顧客是折扣與便利；對企業是**預收現金流**與提高轉換成本（寄了 20 杯就不會去別家）；對營運是需求預測資料。

反面對照：很多傳統零售的「數位轉型」是做一個 App，但 App 裡的會員點數跟門市不互通、線上買的不能到店退、客服看不到你在 App 上的紀錄。**通路數位化了，顧客旅程卻沒有整合**——這正是把數位轉型誤解為「搬上網」的典型後果。`,
